   "ps": "محاورې په طبیعي ډول وکاروئ، دلیل وړاندې کړئ او هره زمانه سمه وکاروئ.",
   "rps": "Muhaawire pa tabiee dawl wakaarawai, daleel wraande krai aw hara zamaana sama wakaarawai.",
   "status": "converted",
   "from": "instructions",
